    tracer_agent_start;
    tracer_agent_stop;
    tracer_agent_validate;
    tracer_agent_runtime_profile_v1;
    tracer_agent_capacity_v1;
    tracer_agent_reclaim_v1;
    tracer_agent_page_monitor_start_v1;
    tracer_agent_page_monitor_stop_v1;
    tracer_agent_object_cache_v33;
    tracer_context_pthread_create_detour;
  local:
    *;
};
